-- Giá tháng: Chị Hoa tháng 10 đến 12/2026 (1509), 3402 tháng 6 đến 12/2026; Anh Tuấn tháng 10 đến 12/2026.
select c, m::date, t, w
from (values
  ('00000000-0000-4000-8000-000000000101'::uuid, date '2026-10-01', 900000, 1300000),
  ('00000000-0000-4000-8000-000000000102'::uuid, date '2026-06-01', 800000, 1100000),
  ('00000000-0000-4000-8000-000000000103'::uuid, date '2026-10-01', 700000, 700000),
  ('00000000-0000-4000-8000-000000000104'::uuid, date '2026-10-01', 1500000, 1500000)
) v(c, tu, t, w)
cross join lateral generate_series(tu, date '2026-12-01', interval '1 month') m;


